'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={records:[],settings:{}}, view='dashboard',filter='today',project=null,space='all',search='',chat=[],online=true,loaded=false;
let queue=[], conflicts=[], sessionReady=false, revealTimer,accountGeneration=0;
const dbReady=new Promise((resolve,reject)=>{const r=indexedDB.open('tgtop-device',1);r.onupgradeneeded=()=>r.result.createObjectStore('private');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
// Offline cache encrypted with a separate local passphrase-derived key. Opt-in only.
let localKey=null,cacheUser='';
function cacheKey(k){if(!cacheUser)throw Error('Enter your username before unlocking offline access.');return location.origin+'|'+cacheUser+'|'+k}
async function dbGet(k){const db=await dbReady;return new Promise(resolve=>{const r=db.transaction('private').objectStore('private').get(cacheKey(k));r.onsuccess=()=>{if(r.result===undefined&&state.account?.is_owner){const legacy=db.transaction('private').objectStore('private').get(k);legacy.onsuccess=()=>resolve(legacy.result)}else resolve(r.result)}})}
async function dbPut(k,v){const db=await dbReady;return new Promise(resolve=>{const t=db.transaction('private','readwrite');t.objectStore('private').put(v,cacheKey(k));t.oncomplete=resolve})}
async function localDerive(pass,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:600000,hash:'SHA-256'},key,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function saveCache(){if(!localKey)return;const iv=crypto.getRandomValues(new Uint8Array(12));const data={state:{...state,records:state.records.filter(r=>['task','note','project'].includes(r.kind)),devices:[],phone_masked:null},queue,conflicts};const bytes=await crypto.subtle.encrypt({name:'AES-GCM',iv},localKey,new TextEncoder().encode(JSON.stringify(data)));await dbPut('cache',{iv,bytes})}
async function enableOffline(){cacheUser=state.account?.username||$('#username')?.value.trim().toLowerCase()||'';if(!cacheUser){toast('Enter your username first.');return}modal('Encrypted offline access',`<p>Enter your local passphrase, or choose a strong one to enable offline access. It encrypts task and note copies on this device. You must unlock these copies after each app restart. Keep it separate from your vault password.</p><label>Local passphrase</label><input id="offlinePass" type="password" autocomplete="new-password">`,async()=>{const pass=$('#offlinePass').value;if(pass.length<12)throw Error('Local passphrase not accepted');let salt=await dbGet('salt');if(!salt){salt=crypto.getRandomValues(new Uint8Array(16));await dbPut('salt',salt)}await dbPut('salt',salt);localKey=await localDerive(pass,salt);const cache=await dbGet('cache');if(cache){try{const data=JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:cache.iv},localKey,cache.bytes)));queue=data.queue||[];conflicts=data.conflicts||[];if(!sessionReady){state=data.state;loaded=true;online=false;render()}}catch{localKey=null;throw Error('Incorrect local passphrase')}}await saveCache();toast('Encrypted offline access unlocked');if(sessionReady)await flushQueue()},'Unlock / enable')}
async function api(path,method='GET',body){const generation=accountGeneration;let r;try{r=await fetch('/api'+path,{method,headers:body instanceof FormData?{'X-TgTop':'1'}:{'Content-Type':'application/json','X-TgTop':'1'},body:body?(body instanceof FormData?body:JSON.stringify(body)):undefined})}catch{online=false;throw Error('Service unavailable. Unlock offline access to edit cached tasks and notes.')}if(generation!==accountGeneration)throw Error('Account changed. Try again.');if(r.status===401){sessionReady=false;throw Error('Sign in to continue')}if(!r.ok){const e=await r.json().catch(()=>({detail:'Request failed'}));if(r.status===409&&e.current){throw Object.assign(Error('This record changed on another device. Refresh and review both versions.'),{current:e.current})}throw Error(typeof e.detail==='string'?e.detail:e.error||'Please check your input')}online=true;return r.headers.get('content-type')?.includes('application/json')?r.json():r.blob()}
function records(kind){return state.records.filter(r=>r.kind===kind&&!r.deleted)}
function record(id){return state.records.find(r=>r.id===id)}
function pname(id){return record(id)?.title||'No project'}
function date(iso){return iso?new Date(iso).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:state.settings.timezone||'America/New_York'}):'No due date'}
function taskDay(t){if(!t.due_at)return '';return new Date(t.due_at).toLocaleDateString('en-CA',{timeZone:state.settings.timezone||'America/New_York'})}
function today(){return new Date().toLocaleDateString('en-CA',{timeZone:state.settings.timezone||'America/New_York'})}
function overdue(t){return t.status!=='done'&&t.due_at&&new Date(t.due_at)<new Date()}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
function modal(title,body,submit,label='Save'){const d=$('#dialog');d.innerHTML=`<form id="modalForm"><div class="section-head"><h2>${esc(title)}</h2><button type="button" class="quiet" data-close aria-label="Close">×</button></div>${body}<div id="modalError" class="danger" role="alert"></div><div class="actions"><button type="button" data-close>Cancel</button>${submit?`<button class="primary" type="submit">${esc(label)}</button>`:''}</div></form>`;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{d.close();d.innerHTML=''});$('#modalForm').onsubmit=async e=>{e.preventDefault();const b=d.querySelector('[type=submit]');b.disabled=true;try{await submit();d.close();d.innerHTML=''}catch(err){$('#modalError').textContent=err.message;b.disabled=false}};d.showModal()}
async function refresh(){const next=await api('/state');if(cacheUser&&next.account?.username!==cacheUser){localKey=null;queue=[];conflicts=[]}cacheUser=next.account?.username||'';state=next;loaded=true;sessionReady=true;await saveCache();render();await flushQueue();await notifications()}
let accountConfigured=true;
function isCloud(){return location.origin!=='http://127.0.0.1:8765'}
function servicePanel(){return `<section class="panel"><h2>${isCloud()?'Shared cloud workspace':'Saved on this computer'}</h2><p>${isCloud()?'Sign into this same service and account on every device. Your projects, tasks, managed files, notes, reminders, and settings share one saved workspace.':'This installation saves to this PC. Connect every device to one hosted service to share your account data.'}</p><p><small>Service: ${esc(location.origin)}<br>${state.server_time?'Last checked '+esc(date(state.server_time)):'Sign in to check saved data'} · ${online?'Connected':'Offline cached information'}</small></p>${window.tgtop?'<button id="cloudConnect">'+(isCloud()?'Change cloud service':'Connect cloud account')+'</button>':''}${isCloud()&&window.tgtop?'<button id="localService">Use this PC’s local workspace</button>':''}<p><small>${queue.length} queued edits · ${conflicts.length} conflicts. External PC file references require their original service computer.</small></p></section>`}
function cloudModal(){if(!window.tgtop){toast('Open your shared TgTop web address on this device.');return}modal('Connect cloud account',`<p>Use the same HTTPS TgTop address on all your computers, then sign in with your cloud username and password.</p><p>Your local data stays on this PC. To move it, create an encrypted backup first, then restore it into your cloud account. Connecting alone does not upload or merge data.</p><label for="hostUrl">TgTop cloud address</label><input id="hostUrl" type="url" required autocomplete="url"><p><small>A hosted TgTop server is required. ChatGPT and Photon do not provide TgTop storage hosting.</small></p>`,async()=>{if(queue.length||conflicts.length)throw Error('Sync queued edits and resolve conflicts before switching services.');await window.tgtop.connect($('#hostUrl').value.trim())},'Check & connect')}
function bindService(){on('cloudConnect',cloudModal);on('localService',()=>modal('Return to local workspace',`<p>This restarts TgTop with this PC’s saved local account. Your cloud account stays on the server. Cloud changes are not copied into local storage.</p>`,async()=>{if(queue.length||conflicts.length)throw Error('Sync queued edits and resolve conflicts first.');await window.tgtop.localService()},'Return to local'))}

function resetAccountView(){accountGeneration++;clearTimeout(revealTimer);calendarMonth=null;resumeDocument=null;resumeDirty=false;localKey=null;cacheUser='';state={records:[],settings:{}};queue=[];conflicts=[];chat=[];project=null;search='';loaded=false;sessionReady=false;const d=$('#dialog');if(d.open)d.close();d.innerHTML=''}
function loginScreen(setup=false){$('#app').innerHTML=`<div class="login"><div class="brand"><img src="/icon.svg" alt="">TgTop</div><span class="eyebrow">Your connected workspace</span><div class="tabs" aria-label="Account access"><button id="loginTab" class="${setup?'':'active'}">Log in</button><button id="signupTab" class="${setup?'active':''}">Sign up</button></div><h1>${setup?'Create your account':'Welcome back.'}</h1><p class="muted">${setup?'Create your own private workspace. Your projects, files, and settings belong to your account.':'Enter your username and password to open your saved workspace.'}</p><p class="banner">${isCloud()?'Cloud account · '+esc(location.host):'Local account · saved on this PC'}</p>${window.tgtop?'<button type="button" id="cloudConnect">Connect cloud account</button>':''}${isCloud()&&window.tgtop?'<button type="button" id="localService">Use local workspace</button>':''}<form id="loginForm">${setup?'<label for="name">Your name</label><input id="name" autocomplete="name" required>':''}<label for="username">Username</label><input id="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9_.-]{2,31}" autocomplete="username" autocapitalize="none" spellcheck="false"><label for="password">${setup?'Create password':'Password'}</label><input id="password" type="password" required autocomplete="${setup?'new-password':'current-password'}">${!setup?'<label for="loginCode">Authenticator or recovery code (if enabled)</label><input id="loginCode" autocomplete="one-time-code" spellcheck="false">':''}${setup?'<label for="confirmPassword">Confirm password</label><input id="confirmPassword" type="password" required autocomplete="new-password">':''}<label for="device">Device name</label><input id="device" value="${esc(navigator.platform.includes('Win')?'Windows PC':'Web device')}" required><p id="loginError" role="alert"></p><button class="primary">${setup?'Sign up':'Log in'}</button></form><button id="offlineLogin" class="quiet">Unlock encrypted offline workspace</button><p><small>Your account and saved work remain after closing TgTop or signing out. Each user has a separate workspace. Vault secrets use a separate master password.</small></p></div>`;bindService();$('#loginTab').onclick=()=>loginScreen(false);$('#signupTab').onclick=()=>loginScreen(true);$('#offlineLogin').onclick=enableOffline;$('#loginForm').onsubmit=async e=>{e.preventDefault();const username=$('#username').value.trim().toLowerCase(),password=$('#password').value,device=$('#device').value,code=$('#loginCode')?.value,b=e.target.querySelector('[type="submit"]')||e.target.querySelector('.primary');b.disabled=true;try{if(setup){if(password!==$('#confirmPassword').value)throw Error('Passwords do not match.');await api('/signup','POST',{username,name:$('#name').value,password});accountConfigured=true}resetAccountView();await api('/login','POST',{username,password,device,code});view=setup?'setup':'dashboard';await refresh()}catch(err){$('#loginError').textContent=err.message==='Use at least 12 characters'?'Choose a stronger password.':err.message}finally{b.disabled=false}}}

const nav=[['dashboard','◈','Overview'],['tasks','✓','My tasks'],['projects','▧','Projects'],['files','▤','File library'],['resume','▥','Resume'],['vault','⌑','Credential vault'],['assistant','✧','AI assistant'],['reminders','◷','Reminders'],['connections','⇄','Connections & devices'],['backup','↺','Backup & restore'],['setup','⚙','Setup & settings']];
function render(){if(!loaded)return;const title=nav.find(n=>n[0]===view)?.[2]||'Workspace';$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img src="/icon.svg" alt="">TgTop<span class="badge">BETA</span></div><div class="nav-label">WORKSPACE</div><nav class="nav">${nav.slice(0,6).map(navButton).join('')}</nav><div class="nav-label">CONNECTED SYSTEM</div><nav class="nav">${nav.slice(6).map(navButton).join('')}</nav><div class="sidebar-foot"><span class="private">● ${esc(state.account?.username||'Private workspace')}</span><p>${online?'Connected to your service':'Offline · cached information'}<br>${queue.length} queued changes</p><button class="quiet" id="signout">Sign out</button></div></aside><main><header class="topbar"><input class="search" id="globalSearch" aria-label="Search workspace" placeholder="Search your workspace…" value="${esc(search)}"><div class="right"><span class="badge">${online?'● Connected':'○ Offline'}</span><button class="quiet" id="theme" aria-label="Toggle dark mode">◐</button><div class="profile"><button class="avatar" id="profileToggle" aria-label="Open profile menu" aria-expanded="false" aria-controls="profileMenu" title="Profile">${esc((state.account?.name||state.account?.username||'T').slice(0,1).toUpperCase())}</button><div class="profile-menu" id="profileMenu" hidden><strong>${esc(state.account?.name||state.account?.username||'Your account')}</strong><span class="muted">${esc(state.account?.username||'Offline workspace')}</span><button id="profileSignout">Sign out</button></div></div></div></header>${!online?'<div class="banner warning">Offline · showing encrypted cached tasks and notes. Edits queue until the service reconnects.</div>':''}${conflicts.length?`<div class="banner warning">${conflicts.length} sync conflict(s) need review. <button id="conflictReview">Review</button></div>`:''}<div id="page"></div></main></div>`;$('.nav').parentElement.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;project=null;search='';render()});$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('theme',document.body.classList.contains('dark')?'dark':'light')};$('#signout').onclick=async()=>{try{await api('/logout','POST',{})}catch{}resetAccountView();loginScreen()};$('#profileSignout').onclick=()=>$('#signout').click();const profileToggle=$('#profileToggle'),profileMenu=$('#profileMenu');const closeProfile=()=>{profileMenu.hidden=true;profileToggle.setAttribute('aria-expanded','false')};profileToggle.onclick=()=>{profileMenu.hidden=!profileMenu.hidden;profileToggle.setAttribute('aria-expanded',String(!profileMenu.hidden));if(!profileMenu.hidden)$('#profileSignout').focus()};document.onclick=e=>{if(!e.target.closest('.profile'))closeProfile()};document.onkeydown=e=>{if(e.key==='Escape'&&!profileMenu.hidden){closeProfile();profileToggle.focus()}};$('#globalSearch').oninput=e=>{search=e.target.value;renderPage()};if($('#conflictReview'))$('#conflictReview').onclick=resolveConflict;renderPage()}
function navButton(n){return `<button data-view="${n[0]}" class="${view===n[0]?'active':''}"><span class="symbol">${n[1]}</span>${n[2]}</button>`}
function heading(kicker,title,desc,button=''){return `<div class="heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}
function taskRows(ts){return ts.length?ts.map(t=>`<div class="task-row"><button class="check ${t.status==='done'?'done':''}" data-complete="${t.id}" aria-label="${t.status==='done'?'Reopen':'Complete'} ${esc(t.title)}">${t.status==='done'?'✓':''}</button><div class="task-body"><button class="task-title ${t.status==='done'?'done-title':''}" data-task="${t.id}">${esc(t.title)}</button><div class="task-meta"><span>${esc(pname(t.project_id))}</span><span>${esc(date(t.due_at))}</span>${t.parent_id?'<span>↳ Subtask</span>':''}${t.dependencies?.length?'<span>↗ Dependencies</span>':''}${t.file_ids?.length?`<span>▤ ${t.file_ids.length} file(s)</span>`:''}${t.recurrence?`<span>↻ ${esc(t.recurrence)}</span>`:''}</div></div><span class="badge ${overdue(t)?'overdue':esc(t.priority||'normal')}">${overdue(t)?'Overdue':esc(t.priority||'normal')}</span><button class="quiet" data-trash="${t.id}" aria-label="Move ${esc(t.title)} to trash">×</button></div>`).join(''):'<div class="empty">A little breathing room.<br>Add a task when you’re ready.</div>'}
function selectedTasks(){return records('task').filter(t=>(!project||t.project_id===project)&&(!search||JSON.stringify(t).toLowerCase().includes(search.toLowerCase())))}
function filteredTasks(){return selectedTasks().filter(t=>filter==='all'||(filter==='done'?t.status==='done':t.status!=='done'&&(filter==='today'?taskDay(t)===today():filter==='overdue'?overdue(t):filter==='upcoming'?t.due_at&&taskDay(t)>today():true))).sort((a,b)=>(a.due_at||'z').localeCompare(b.due_at||'z'))}
function projectCard(p){const ts=records('task').filter(t=>t.project_id===p.id),done=ts.filter(t=>t.status==='done').length;return `<article class="panel project" data-project="${p.id}" tabindex="0" role="button"><div class="section-head"><span class="project-icon">${p.space==='school'?'▱':p.space==='work'?'▣':'◈'}</span><span class="badge">${esc(p.space)}</span></div><h3>${esc(p.title)}</h3><small>${esc(p.description||'Your tasks, files, and ideas.').slice(0,90)}</small><div class="progress"><span style="width:${ts.length?done/ts.length*100:0}%"></span></div><div class="section-head"><small>${done} of ${ts.length} tasks complete</small><small>${p.ai_allowed?'✧ AI allowed':'⌑ Private'}</small></div></article>`}
function renderPage(){const el=$('#page');if(!el)return;
if(view==='dashboard'){const tasks=records('task'),open=tasks.filter(t=>t.status!=='done'),due=open.filter(t=>taskDay(t)===today()),late=open.filter(overdue);el.innerHTML=heading('YOUR DAY, CONNECTED','Make room for what matters.',new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',timeZone:state.settings.timezone||'America/New_York'}),'<button class="primary" id="addTask">＋ New task</button>')+`<div class="stats"><div class="stat"><small>Today’s focus</small><strong>${due.length}</strong><small>tasks on your calendar</small></div><div class="stat"><small>In progress</small><strong>${open.length}</strong><small>open tasks across your spaces</small></div><div class="stat"><small>Needs attention</small><strong>${late.length}</strong><small>overdue tasks</small></div><div class="stat"><small>Projects</small><strong>${records('project').length}</strong><small>one connected workspace</small></div></div><div class="columns"><div><section class="panel"><div class="section-head"><h2>Your next steps</h2><button class="quiet" data-go="tasks">View all →</button></div><div class="tabs">${['today','upcoming','overdue','all'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div>${taskRows(filteredTasks().slice(0,8))}</section><div class="section-head"><h2>Project spaces</h2><button class="quiet" id="addProject">＋ New project</button></div><div class="grid">${records('project').slice(0,3).map(projectCard).join('')}</div></div><aside><div class="focus-card"><small>A CLEARER HEADSPACE</small><h2>Everything connected.<br>One next step.</h2><p>Bring your work, school, and personal projects together. Start with the task in front of you.</p></div><section class="panel"><h2>Coming up</h2>${records('reminder').filter(r=>r.state==='pending').slice(0,4).map(r=>`<div class="list-item">${esc(record(r.task_id)?.title||'Task reminder')}<br><small>${date(r.due_at)} · ${r.channel}</small></div>`).join('')||'<p class="muted">No reminders scheduled.</p>'}<button class="quiet" data-go="reminders">Manage reminders →</button></section><section class="panel"><h2>Recent activity</h2>${records('activity').slice(-5).reverse().map(a=>`<div class="list-item">${esc(a.action.replaceAll('_',' '))}<br><small>${date(a.created_at)}</small></div>`).join('')}</section></aside></div>`}
else if(view==='tasks'){el.innerHTML=calendarHtml()}
else if(view==='projects'&&!project){el.innerHTML=heading('PROJECT SPACES','A home for every project.','Personal projects, school, and work — connected to what comes next.','<button class="primary" id="addProject">＋ New project</button>')+`<div class="tabs">${['all','personal','school','work'].map(f=>`<button data-space="${f}" class="${space===f?'active':''}">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div><div class="grid">${records('project').filter(p=>(space==='all'||p.space===space)&&p.title.toLowerCase().includes(search.toLowerCase())).map(projectCard).join('')}</div>`}
else if(view==='projects'&&project){const p=record(project);el.innerHTML=heading(esc(p.space),esc(p.title),esc(p.description||'Tasks, notes, files, and decisions for this project.'),`<div class="actions"><button id="editProject">Edit project</button><button class="primary" id="addTask">＋ New task</button></div>`)+`<div class="banner">AI access: <strong>${p.ai_allowed?'Allowed':'Private'}</strong>. File access is controlled separately in the file library. <button id="toggleAI">${p.ai_allowed?'Disable':'Allow'} AI access</button></div><section class="panel"><h2>Project tasks</h2>${taskRows(selectedTasks())}</section><div class="columns"><section class="panel"><div class="section-head"><h2>Notes & decisions</h2><button id="addNote">＋ Note</button></div>${records('note').filter(n=>n.project_id===project).map(n=>`<div class="list-item"><button class="quiet" data-note="${n.id}">${esc(n.title)}</button><p class="note">${esc(n.body)}</p></div>`).join('')||'<p class="muted">Capture your next idea.</p>'}</section><section class="panel"><h2>Connected files</h2>${records('file').filter(f=>f.project_id===project).map(f=>`<div class="list-item"><button class="quiet" data-preview="${f.id}">▤ ${esc(f.title)}</button></div>`).join('')||'<p class="muted">Add files from the library.</p>'}<h2>Conversations</h2>${records('conversation').filter(c=>c.project_id===project).map(c=>`<div class="list-item">${esc(c.title)}<br><small>${c.source_ids?.length||0} source references</small></div>`).join('')}</section></div>`}
else if(view==='files'){el.innerHTML=heading('FILE LIBRARY','Keep the context close.','Encrypted managed uploads and approved local references.','<div class="actions"><button id="addFolder">＋ Folder</button><button id="addRef">Link local file</button><button class="primary" id="upload">＋ Upload file</button></div>')+`<div class="grid">${records('folder').map(f=>`<div class="panel"><h3>▱ ${esc(f.title)}</h3><small>${esc(pname(f.project_id))}</small></div>`).join('')}</div><section class="panel">${records('file').filter(f=>JSON.stringify(f).toLowerCase().includes(search.toLowerCase())).map(f=>`<div class="file-row"><span>▤</span><div class="info"><h3>${esc(f.title)}</h3><small>${esc(pname(f.project_id))} · ${Math.ceil(f.size/1024)} KB · ${f.managed?'Managed':'Local reference'}${f.folder_id?' · '+esc(record(f.folder_id)?.title):''}<br>${esc((f.tags||[]).join(' · '))}</small></div><div class="actions"><button data-preview="${f.id}">Preview</button><button data-fileedit="${f.id}">Edit</button><button data-fileai="${f.id}">${f.ai_allowed?'AI allowed':'AI private'}</button><a href="/api/files/${f.id}/content" download>Download</a><button data-trash="${f.id}" class="danger">Trash</button></div></div>`).join('')||'<div class="empty">Upload a file and connect it to a project or task.</div>'}</section>`}
else if(view==='resume'){el.innerHTML=heading('RESUME','Your resume, ready to edit.','Edit your account resume across devices, or link an original Word file on a local service.','<div class="actions"><button id="resumeUpload">Upload resume</button><button id="resumeDownload" disabled>Download Word file</button><button id="resumeLink">Link local file</button><button id="resumeReload">Reload file</button><button id="resumeHistory">Version history</button><button id="resumeRestore" disabled>Restore previous save</button><button class="primary" id="resumeSave" disabled>Save to computer</button></div>')+'<section class="panel"><p><small>Text editing preserves existing Word formatting. Use Word for new sections, tables, or page layout. Resume contents stay outside AI access and search.</small></p><div id="resumeEditor"></div></section>';loadResume()}
else if(view==='vault'){el.innerHTML=heading('CREDENTIAL VAULT','Private by default.','Secrets stay outside AI context, search results, notifications, and SMS.','<button id="vaultLock">Lock vault</button>')+`<div class="banner">Vault locks automatically after 5 minutes. Explicit unlock is required before saving or revealing a secret. Recovery requires your master password and a backup; no reset can decrypt a forgotten vault password.</div><section class="panel"><div class="section-head"><h2 id="vaultState">⌑ Checking vault…</h2><div class="actions"><button id="vaultUnlock">Unlock</button><button class="primary" id="addCredential">＋ Credential</button></div></div>${records('credential').map(c=>`<div class="file-row"><div class="info"><h3>${esc(c.title)}</h3><small>${esc(pname(c.project_id))} · ${esc(c.username)}</small><p>••••••••••••</p></div><button data-reveal="${c.id}">Reveal</button><button data-usecredential="${c.id}">Check OpenAI key</button><button data-trash="${c.id}" class="danger">Trash</button></div>`).join('')||'<div class="empty">Set up your master password to start your vault.</div>'}</section>`;api('/vault/status').then(s=>{if($('#vaultState'))$('#vaultState').textContent=s.configured?(s.locked?'⌑ Vault locked':'◇ Vault unlocked · 5 minute limit'):'⌑ Vault needs setup'}).catch(e=>toast(e.message))}
else if(view==='assistant'){el.innerHTML=heading('AI ASSISTANT','Think with your context.','Visible sources. Controlled actions. Your permissions.','<button id="chatgptSetup">Connect ChatGPT</button>')+`<div class="banner">${state.chatgpt?.connected?(state.chatgpt?.plan_enabled?(state.chatgpt.model?'ChatGPT ready · '+esc(state.chatgpt.model)+'.':'ChatGPT connected. Choose a model in Connections to use your plan.'):'ChatGPT account linked; plan permission needed.'):'Live AI is not connected. Continue with ChatGPT in Connections. The local-search simulator makes no AI calls.'} Codex connects separately through MCP in Connections. Source documents are untrusted data.</div><section class="panel"><label>Project context</label><select id="chatProject"><option value="">All AI-authorized projects</option>${records('project').filter(p=>p.ai_allowed).map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select><div class="chat">${chat.map(c=>`<div class="message"><small>${esc(c.mode||'You')}</small><p>${esc(c.text)}</p>${(c.sources||[]).map(s=>`<button class="source" data-source="${s.id}">${esc(s.title)} · ${esc(s.kind)}</button>`).join('')}${(c.actions||[]).map(a=>`<small>${esc(a.tool)} · ${esc(a.status)}</small>`).join('')}</div>`).join('')||'<div class="empty">Search your projects, summarize a note, or create a task.<br>Enable access in the project workspace first.</div>'}</div><form id="chatForm" class="chat-input"><input id="chatMessage" required placeholder="What’s next in my project?" aria-label="Message assistant"><button class="primary">Send →</button></form></section>`}
else if(view==='reminders'){el.innerHTML=heading('REMINDERS','A nudge at the right time.','Durable scheduling with quiet hours, snoozing, and delivery history.','<button class="primary" id="addReminder">＋ Reminder</button>')+`<div class="banner">Timezone: ${esc(state.settings.timezone)} · Quiet hours ${esc(state.settings.quiet_start)}–${esc(state.settings.quiet_end)}. Every dated task automatically schedules an SMS one hour before its deadline when enabled in settings. These automatic texts bypass quiet hours. SMS requires an always-on host; desktop delivery waits for a connected device.</div><section class="panel"><h2>Scheduled reminders</h2>${records('reminder').map(r=>`<div class="file-row"><div class="info"><h3>${esc(record(r.task_id)?.title||'Task')}</h3><small>${date(r.due_at)} · ${esc(r.channel)}${r.recurrence?' · '+esc(r.recurrence):''}</small></div><span class="badge">${esc(r.state||'pending')}</span><button data-snooze="${r.id}">Snooze 15m</button>${r.state==='failed'?`<button data-retry="${r.id}">Review & retry</button>`:''}<button data-trash="${r.id}" class="danger">Cancel</button></div>`).join('')||'<div class="empty">No reminders scheduled.</div>'}</section><section class="panel"><h2>Delivery history & missed notifications</h2>${records('delivery').slice().reverse().map(d=>`<div class="list-item">${esc(record(d.task_id)?.title||'Task reminder')} · ${esc(d.channel)} · <strong>${esc(d.status)}</strong><br><small>${date(d.created_at)} ${esc(d.error||'')}</small>${d.status==='waiting_device'?` <button data-ack="${d.id}">Acknowledge</button>`:''}</div>`).join('')||'<p class="muted">No delivery attempts yet.</p>'}</section>`}
else if(view==='connections'){el.innerHTML=heading('CONNECTIONS','Connected, on your terms.','Manage authorized devices, integrations, and approved workflows.','<button id="schoolConnect" class="primary">School connections</button>')+servicePanel()+`<div class="grid"><section class="panel"><h2>Messaging service</h2><p id="messagingStatus">Checking connection…</p><button class="primary" id="messagingSetup">Connect Photon or Twilio</button><p>${state.phone_masked?esc(state.phone_masked):'No phone configured'} · ${state.settings.phone_verified?'Verified ('+esc(state.settings.phone_verification_mode)+')':'Not verified'}</p><button id="phoneSetup">Configure & verify</button><p><small>Development verification does not prove real phone ownership.</small></p><details><summary>Development simulator</summary><p>No real messages are sent.</p><button id="smsSim">Open command simulator</button></details></section><section class="panel"><h2>ChatGPT</h2><p>${state.chatgpt?.connected?'Connected · '+esc(state.chatgpt.model||'Choose a model'):'Use your eligible ChatGPT plan for AI.'}</p><button id="chatgptSetup">Manage ChatGPT</button><p><small>Phone AI: start your message with AI. Only fixed acknowledgments and task counts go back through Photon.</small></p><h2>Codex MCP</h2><p>Expose authorized search, task creation, and reminders through the official MCP SDK.</p><button id="mcpToken">Create restricted token</button><p><small>Tokens expire in 7 days and can be revoked below. Vault and backups are never exposed.</small></p></section><section class="panel"><h2>Device & sync</h2><p>Use the same hosted service on every device. Local installations keep separate data until connected to a common host.</p><button id="offlineEnable">Unlock offline editing</button><button id="syncNow">Sync now</button><p><small>${queue.length} queued edits · ${conflicts.length} conflicts</small></p></section></div><section class="panel"><h2>Phone command history</h2><p>Actions and replies have separate outcomes. Review provider history before retrying an uncertain reply. Private message content stays out of this history.</p>${records('remote_command').slice(-30).reverse().map(r=>`<div class="file-row"><div class="info"><h3>${esc(r.title)}</h3><small>${date(r.created_at)} · Action: ${esc(r.status)} · Reply: ${esc(r.reply_status)} ${esc(r.error||'')}</small></div>${r.status==='failed'?`<button data-actionretry="${r.id}">Review action</button>`:''}${r.reply_status==='needs_review'&&r.status==='succeeded'?`<button data-replyretry="${r.id}">Review reply</button>`:''}</div>`).join('')||'<p>No commands received yet.</p>'}</section><section class="panel"><h2>Enrolled devices & sessions</h2>${(state.devices||[]).map(d=>`<div class="file-row"><div class="info"><h3>${esc(d.device)}${d.id===state.device_id?' · This device':''}</h3><small>Expires ${date(d.expires)}</small></div><span class="badge">${d.revoked?'Revoked':'Authorized'}</span>${!d.revoked?`<button data-revoke="${d.id}">Revoke</button>`:''}</div>`).join('')}</section><section class="panel"><div class="section-head"><h2>Approved device workflows</h2><button id="requestWorkflow">＋ Backup workflow</button></div><p><small>Allowlist: encrypted backup only. No arbitrary shell access. 30 second execution limit. Files can be referenced only in server-approved folders.</small></p>${records('workflow').map(w=>`<div class="file-row"><div class="info"><h3>${esc(w.title)}</h3><small>${esc(w.scope)} · ${esc(w.status)} ${esc(w.error||'')}</small></div>${w.status==='awaiting_approval'?`<button data-approve="${w.id}">Approve on this device</button>`:''}${w.status==='waiting_device'&&w.device_id===state.device_id?`<button data-run="${w.id}">Run backup</button>`:''}${!['completed','cancelled'].includes(w.status)?`<button data-cancel="${w.id}">Cancel</button>`:''}</div>`).join('')}</section>`}
else if(view==='backup'){el.innerHTML=heading('BACKUP & RECOVERY','Keep a way back.','Encrypted snapshots, portable exports, and recoverable deletion.')+`<div class="grid"><section class="panel"><h2>Encrypted backup</h2><p>Includes all managed files and vault ciphertext. Protect the snapshot with a separate backup password.</p><button class="primary" id="backupCreate">Create backup</button><p><small>Vault master password still required after restore. External referenced files are not copied.</small></p></section><section class="panel"><h2>Restore a snapshot</h2><p>Replaces the service’s current data and revokes every device session. A pre-restore encrypted snapshot is kept locally.</p><button id="backupRestore">Restore backup</button></section><section class="panel"><h2>Portable export</h2><p>Export project, task, note, and file metadata as JSON. Vault and account settings are excluded.</p><button id="export">Download JSON export</button><p><small>Exported JSON contains private workspace content; protect the downloaded file.</small></p></section></div><section class="panel"><h2>Recoverable trash</h2><div id="trashList" class="muted">Loading…</div></section>`;api('/trash').then(rs=>{if($('#trashList')){$('#trashList').innerHTML=rs.map(r=>`<div class="file-row"><div class="info">${esc(r.title||r.kind)} · ${esc(r.kind)}</div><button data-restore="${r.id}">Restore</button></div>`).join('')||'Trash is empty.';bindPage()}}).catch(e=>toast(e.message))}
else if(view==='setup'){el.innerHTML=heading('SETUP & SETTINGS','Make TgTop yours.','A guided path from local workspace to connected devices.')+`<div class="onboarding-steps"><section class="panel"><span class="eyebrow">01 · ACCOUNT & STORAGE</span><h2>Your private workspace</h2><p>Account passwords use Argon2id. Records and uploads are encrypted on disk with a service key. Vault secrets use your separate master password.</p><button data-go="vault">Set up vault →</button><button id="accountSecurity">Account security</button><p><small>Keep the runtime folder private; the service can decrypt normal records. Enable encrypted offline storage separately.</small></p></section><section class="panel"><span class="eyebrow">02 · AI & PHONE</span><h2>Choose what connects</h2><p>Continue with ChatGPT to use your eligible plan for live AI. Connect Photon or Twilio for phone messaging.</p><button data-go="connections">Manage connections →</button><p><small>API usage, SMS messages, verification, a phone number, and hosting incur provider costs.</small></p></section><section class="panel"><span class="eyebrow">03 · OTHER DEVICES</span><h2>Take it with you</h2><p>Install the Windows app or add this web app to your phone’s home screen. Connect devices to one HTTPS service for shared data.</p><button id="desktopConnect">Connect to hosted service</button>${window.tgtop?.startupStatus?'<button id="desktopStartup">Windows background settings</button>':''}<p><small>Cloud reminders work while your PC is off only if your backend host stays online. Device workflows wait for the approved device.</small></p></section></div><section class="panel"><h2>Reminder preferences</h2><form id="settingsForm"><div class="row"><div><label>Timezone</label><input id="tz" value="${esc(state.settings.timezone)}" required></div><div><label>Quiet hours start</label><input id="quietStart" type="time" value="${esc(state.settings.quiet_start)}"></div><div><label>Quiet hours end</label><input id="quietEnd" type="time" value="${esc(state.settings.quiet_end)}"></div></div><label><input id="desktopChannel" type="checkbox" ${(state.settings.channels||[]).includes('desktop')?'checked':''}> Desktop notifications</label><label><input id="smsChannel" type="checkbox" ${(state.settings.channels||[]).includes('sms')?'checked':''}> SMS reminders</label><label><input id="calendarSms" type="checkbox" ${state.settings.calendar_sms!==false?'checked':''}> Text me one hour before every dated calendar task</label><p><small>Automatic calendar texts bypass quiet hours. Tasks added less than an hour before their deadline send immediately. Overdue tasks do not send late texts. Your phone must be verified and your messaging service connected.</small></p><div class="actions"><button class="primary">Save settings</button><button type="button" id="notificationPermission">Enable desktop notifications</button></div></form></section><section class="panel"><h2>Where data is decrypted</h2><p>Normal records and files are decrypted inside the service for authenticated requests. Authorized content may be sent to the OpenAI API when you enable AI access. Vault secrets are decrypted only during an explicit unlock, inside service memory; the AI and MCP have no vault tool. HTTPS protects transport for remote devices. Offline task and note copies are decrypted in your browser after your local passphrase unlock.</p><p><small>This is an early local release. Read the setup and security documentation before exposing a backend to the internet.</small></p></section>`}
bindPage();bindPersonal()}
function on(id,fn){const e=$('#'+id);if(e)e.onclick=()=>Promise.resolve(fn()).catch(err=>toast(err.message))}
function bind(selector,fn){document.querySelectorAll(selector).forEach(e=>e.onclick=()=>Promise.resolve(fn(e)).catch(err=>toast(err.message)))}
function bindPage(){bindService();on('schoolConnect',schoolModal);on('desktopStartup',async()=>{const status=await window.tgtop.startupStatus();if(!status.supported){toast('Install the Windows application to configure startup');return}modal('Windows background settings',`<p>Closing the Windows window keeps TgTop in the system tray so it can receive desktop reminders. Choose Quit TgTop from the tray to stop it.</p><label><input id="startupEnabled" type="checkbox" ${status.enabled?'checked':''}> Open TgTop when I sign in to Windows</label>`,async()=>{await window.tgtop.startupSet($('#startupEnabled').checked);toast('Windows startup preference saved')},'Save preference')});on('accountSecurity',securityModal);on('chatgptSetup',chatgptModal);on('addTask',()=>taskModal());on('addProject',()=>projectModal());on('editProject',()=>projectModal(record(project)));on('addNote',()=>noteModal());on('addFolder',folderModal);on('upload',uploadModal);on('addRef',referenceModal);on('toggleAI',async()=>{const p=record(project);await patch(p,{ai_allowed:!p.ai_allowed})});on('vaultUnlock',vaultUnlock);on('vaultLock',async()=>{await api('/vault/lock','POST',{});await refresh()});on('addCredential',credentialModal);on('addReminder',reminderModal);on('phoneSetup',phoneModal);on('smsSim',smsModal);on('mcpToken',async()=>{const r=await api('/mcp-token','POST',{});modal('Restricted Codex token',`<p>Copy once into your private environment as TGTOP_MCP_TOKEN. Keep it out of prompts and source control. Expires ${date(r.expires)}.</p><pre>${esc(r.token)}</pre><p>Run: <code>python -m app.mcp_server</code> through Codex’s MCP configuration. See README for setup.</p>`,null);await refresh()});on('offlineEnable',enableOffline);on('syncNow',async()=>{await refresh();toast('Synced with service')});on('backupCreate',()=>backupModal());on('backupRestore',restoreModal);on('export',async()=>download(new Blob([JSON.stringify(await api('/export'),null,2)],{type:'application/json'}),'TgTop-export.json'));on('requestWorkflow',async()=>{await api('/workflows/backup','POST',{});await refresh()});on('desktopConnect',cloudModal);on('notificationPermission',async()=>{if(window.tgtop)toast('Native notifications are enabled in the Windows app');else if('Notification'in window)toast('Notification permission: '+await Notification.requestPermission());else toast('This browser does not support desktop notifications')});
bind('[data-go]',e=>{view=e.dataset.go;project=null;render()});bind('[data-filter]',e=>{filter=e.dataset.filter;renderPage()});bind('[data-space]',e=>{space=e.dataset.space;renderPage()});bind('[data-project]',e=>{project=e.dataset.project;view='projects';search='';render()});document.querySelectorAll('[data-project]').forEach(e=>e.onkeydown=ev=>{if(ev.key==='Enter'){e.click()}});bind('[data-task]',e=>taskModal(record(e.dataset.task)));bind('[data-complete]',async e=>{const t=record(e.dataset.complete);await patch(t,{status:t.status==='done'?'open':'done'})});bind('[data-note]',e=>noteModal(record(e.dataset.note)));bind('[data-trash]',e=>trashModal(record(e.dataset.trash)));bind('[data-preview]',e=>preview(e.dataset.preview));bind('[data-fileedit]',e=>fileModal(record(e.dataset.fileedit)));bind('[data-fileai]',async e=>{const f=record(e.dataset.fileai);await patch(f,{ai_allowed:!f.ai_allowed})});bind('[data-usecredential]',e=>modal('Authorize provider credential use',`<p>Sends this vault secret to OpenAI only, to check API access. The AI never receives the key. Explicit vault unlock required.</p>`,async()=>{const r=await api('/integrations/openai/check','POST',{credential_id:e.dataset.usecredential,confirm:true});toast(r.status)},'Authorize check'));bind('[data-reveal]',async e=>{const r=await api('/vault/reveal','POST',{id:e.dataset.reveal});modal('Revealed secret',`<p>This reveal closes in 20 seconds. Keep your screen private.</p><pre>${esc(r.secret)}</pre>`,null);clearTimeout(revealTimer);revealTimer=setTimeout(()=>{$('#dialog').close();$('#dialog').innerHTML=''},20000)});bind('[data-snooze]',async e=>{await api('/reminders/'+e.dataset.snooze+'/snooze','POST',{minutes:15});await refresh()});bind('[data-retry]',e=>modal('Review before retry',`<p>Check Twilio’s message history first. A previous request may have succeeded even if its response was lost. Retrying could send a second message.</p>`,async()=>{await api('/reminders/'+e.dataset.retry+'/retry','POST',{confirm:true});await refresh()},'Confirm retry'));bind('[data-ack]',async e=>{await api('/deliveries/'+e.dataset.ack+'/ack','POST',{});await refresh()});bind('[data-actionretry]',e=>modal('Retry the failed phone action?', '<p>The previous action did not commit. TgTop will attempt the same request again using your current workspace. Successful actions cannot be retried here.</p>',async()=>{await api('/remote/'+e.dataset.actionretry+'/retry-action','POST',{confirm:true});await refresh()},'Retry action'));bind('[data-replyretry]',e=>modal('Retry this phone reply?', '<p>The action has already completed and will not run again. Check your provider message history first. Retrying an uncertain reply can send it twice.</p>',async()=>{await api('/remote/'+e.dataset.replyretry+'/retry-reply','POST',{confirm:true});await refresh()},'Retry reply'));bind('[data-revoke]' ,e=>modal('Revoke this session?',`<p>This device or integration will need to sign in again.</p>`,async()=>{await api('/devices/'+e.dataset.revoke+'/revoke','POST',{});if(e.dataset.revoke===state.device_id){loaded=false;loginScreen()}else await refresh()},'Revoke'));bind('[data-restore]',async e=>{await api('/records/'+e.dataset.restore+'/restore','POST',{});await refresh()});bind('[data-approve]',e=>modal('Approve backup workflow?',`<p>Allows this device to download an encrypted snapshot when you run it. No data is shared externally.</p>`,async()=>{await api('/workflows/'+e.dataset.approve+'/approve','POST',{confirm:true});await refresh()},'Approve'));bind('[data-run]',e=>backupModal(e.dataset.run));bind('[data-cancel]',async e=>{await api('/workflows/'+e.dataset.cancel+'/cancel','POST',{});await refresh()});bind('[data-source]',e=>{const r=record(e.dataset.source);if(r?.kind==='task')taskModal(r);else if(r?.kind==='file')preview(r.id);else modal('Source reference',`<pre>${esc(JSON.stringify(r,null,2))}</pre>`,null)});
if($('#chatForm'))$('#chatForm').onsubmit=async e=>{e.preventDefault();const generation=accountGeneration,message=$('#chatMessage').value,pid=$('#chatProject').value;chat.push({text:message});chat.push({text:'Searching authorized context…',mode:'Working'});renderPage();try{const r=await api('/assistant','POST',{message,project_id:pid||null});if(generation!==accountGeneration)return;chat.pop();chat.push({text:r.answer,...r});await refresh()}catch(err){if(generation!==accountGeneration)return;chat.pop();chat.push({text:err.message,mode:'Failed'});renderPage()}};
if($('#settingsForm'))$('#settingsForm').onsubmit=async e=>{e.preventDefault();try{await api('/settings','POST',{calendar_sms:$('#calendarSms').checked,timezone:$('#tz').value,quiet_start:$('#quietStart').value,quiet_end:$('#quietEnd').value,channels:[$('#desktopChannel').checked?'desktop':null,$('#smsChannel').checked?'sms':null].filter(Boolean)});await refresh();toast('Settings saved')}catch(err){toast(err.message)}}}
function projectOptions(selected){return records('project').map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.title)} · ${esc(p.space)}</option>`).join('')}
async function patch(r,data){const proposed={...r,...data};if(!online&&['task','note'].includes(r.kind)){if(!localKey)throw Error('Unlock encrypted offline access first');const change={operation_id:crypto.randomUUID(),id:r.id,kind:r.kind,version:r.version,data:proposed};const pending=queue.find(q=>q.id===r.id);if(pending){pending.data=proposed}else queue.push(change);state.records=state.records.map(x=>x.id===r.id?proposed:x);await saveCache();render();return}try{await api('/records/'+r.id,'PATCH',{...data,version:r.version});await refresh()}catch(e){if(e.current){conflicts.push({operation_id:crypto.randomUUID(),id:r.id,kind:r.kind,current:e.current,proposed});render();resolveConflict()}else throw e}}
async function create(kind,data){if(!online&&['task','note'].includes(kind)){if(!localKey)throw Error('Unlock offline access first');const id=crypto.randomUUID();queue.push({operation_id:crypto.randomUUID(),id,kind,data});state.records.push({...data,id,kind,version:0,updated_at:new Date().toISOString()});await saveCache();render();return}await api('/records/'+kind,'POST',data);await refresh()}
async function flushQueue(){if(!online||!queue.length||!sessionReady)return;const result=await api('/sync','POST',{changes:queue});const completed=new Set(result.results.filter(r=>r.status==='saved').map(r=>r.operation_id));const bad=result.results.filter(r=>r.status==='conflict');for(const r of bad){const q=queue.find(q=>q.operation_id===r.operation_id);conflicts.push({...r,id:q.id,kind:q.kind})}const badIds=new Set(bad.map(r=>r.operation_id));queue=queue.filter(q=>!completed.has(q.operation_id)&&!badIds.has(q.operation_id));await saveCache();state=await api('/state');render()}
function resolveConflict(){const c=conflicts[0];if(!c)return;modal('Review sync conflict',`<p>Another device changed this record. Compare both versions before saving. Deleted records must be restored in Trash first.</p><h3>Service version</h3><pre>${esc(JSON.stringify(c.current,null,2))}</pre><h3>Your proposed version</h3><pre>${esc(JSON.stringify(c.proposed,null,2))}</pre><label>Resolution</label><select id="resolution"><option value="server">Keep service version</option>${!c.current.deleted?'<option value="mine">Replace with my proposed version</option>':''}</select>`,async()=>{if($('#resolution').value==='mine')await api('/records/'+c.id,'PATCH',{...c.proposed,version:c.current.version});conflicts.shift();await refresh();setTimeout(resolveConflict,100)},'Resolve conflict')}
function taskModal(t){const tasks=records('task').filter(x=>x.id!==t?.id),files=records('file');modal(t?'Edit task':'Create task',`<label>Task</label><input id="taskTitle" required value="${esc(t?.title||'')}" placeholder="What needs to happen?"><div class="row"><div><label>Project</label><select id="taskProject">${projectOptions(t?.project_id||project)}</select></div><div><label>Priority</label><select id="priority">${['low','normal','high','urgent'].map(p=>`<option ${p===(t?.priority||'normal')?'selected':''}>${p}</option>`).join('')}</select></div></div><div class="row"><div><label>Due date & time (${esc(state.settings.timezone||'America/New_York')})</label><input id="due" type="datetime-local" value="${t?.due_at?localDatetime(t.due_at):''}"></div><div><label>Repeat</label><select id="repeat">${['','daily','weekly','monthly'].map(p=>`<option value="${p}" ${p===t?.recurrence?'selected':''}>${p||'Does not repeat'}</option>`).join('')}</select></div></div><div class="row"><div><label>Status</label><select id="taskStatus">${['open','doing','done'].map(s=>`<option ${s===(t?.status||'open')?'selected':''}>${s}</option>`).join('')}</select></div><div><label>Parent task (subtask)</label><select id="parent"><option value="">None</option>${tasks.map(x=>`<option value="${x.id}" ${x.id===t?.parent_id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div></div><label>Dependencies</label><select id="deps" multiple>${tasks.map(x=>`<option value="${x.id}" ${t?.dependencies?.includes(x.id)?'selected':''}>${esc(x.title)}</option>`).join('')}</select><label>Linked files</label><select id="linkedFiles" multiple>${files.map(x=>`<option value="${x.id}" ${t?.file_ids?.includes(x.id)?'selected':''}>${esc(x.title)}</option>`).join('')}</select><label>Details</label><textarea id="taskBody">${esc(t?.body||'')}</textarea>`,async()=>{const data={title:$('#taskTitle').value,project_id:$('#taskProject').value,priority:$('#priority').value,due_at:$('#due').value?accountInstant($('#due').value):null,recurrence:$('#repeat').value||null,status:$('#taskStatus').value,parent_id:$('#parent').value||null,dependencies:[...$('#deps').selectedOptions].map(o=>o.value),file_ids:[...$('#linkedFiles').selectedOptions].map(o=>o.value),body:$('#taskBody').value};t?await patch(t,data):await create('task',data)})}
function localDatetime(iso){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:state.settings.timezone||'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso));const v=Object.fromEntries(parts.map(p=>[p.type,p.value]));return `${v.year}-${v.month}-${v.day}T${v.hour}:${v.minute}`}
function accountInstant(value){const target=Date.parse(value+'Z');let guess=target;for(let i=0;i<4;i++){const shown=Date.parse(localDatetime(new Date(guess).toISOString())+'Z');const delta=target-shown;if(!delta)break;guess+=delta}if(localDatetime(new Date(guess).toISOString())!==value)throw Error('This time does not exist because of daylight saving time. Choose a different time.');return new Date(guess).toISOString()}
function projectModal(p){modal(p?'Edit project':'New project',`<label>Name</label><input id="ptitle" required value="${esc(p?.title||'')}"><label>Space</label><select id="pspace">${['personal','school','work'].map(s=>`<option ${s===p?.space?'selected':''}>${s}</option>`).join('')}</select><label>Description</label><textarea id="pbody">${esc(p?.description||'')}</textarea>`,async()=>{const d={title:$('#ptitle').value,space:$('#pspace').value,description:$('#pbody').value};p?await patch(p,d):await create('project',{...d,ai_allowed:false})})}
function noteModal(n){modal(n?'Edit note':'New note',`<label>Title</label><input id="ntitle" required value="${esc(n?.title||'')}"><label>Project</label><select id="nproject">${projectOptions(n?.project_id||project)}</select><label>Note / decision</label><textarea id="nbody">${esc(n?.body||'')}</textarea>`,async()=>{const d={title:$('#ntitle').value,body:$('#nbody').value,project_id:$('#nproject').value};n?await patch(n,d):await create('note',d)})}
function folderModal(){modal('Create folder',`<label>Name</label><input id="folderTitle" required><label>Project</label><select id="folderProject">${projectOptions(project)}</select>`,async()=>create('folder',{title:$('#folderTitle').value,project_id:$('#folderProject').value}))}
function uploadModal(){modal('Upload managed file',`<p>Files are encrypted in application storage. Maximum 50 MB. AI access starts disabled.</p><label>File</label><input id="uploadFile" type="file" required><label>Project</label><select id="uploadProject">${projectOptions(project)}</select><label>Folder</label><select id="uploadFolder"><option value="">No folder</option>${records('folder').map(f=>`<option value="${f.id}">${esc(f.title)}</option>`).join('')}</select><label>Tags (comma separated)</label><input id="uploadTags">`,async()=>{const f=new FormData();f.append('file',$('#uploadFile').files[0]);f.append('project_id',$('#uploadProject').value);f.append('folder_id',$('#uploadFolder').value);f.append('tags',$('#uploadTags').value);await api('/files','POST',f);await refresh()},'Upload')}
function referenceModal(){modal('Reference an approved local file',`<p>Only folders configured in TGTOP_APPROVED_ROOTS on the service are accessible. References require that device to stay available.</p><label>Absolute file path</label><input id="refpath" required><label>Project</label><select id="refproject">${projectOptions(project)}</select>`,async()=>{await api('/files/reference','POST',{path:$('#refpath').value,project_id:$('#refproject').value});await refresh()})}
function fileModal(f){modal('Edit file details',`<label>Name</label><input id="ftitle" value="${esc(f.title)}" required><label>Project</label><select id="fproject">${projectOptions(f.project_id)}</select><label>Tags</label><input id="ftags" value="${esc((f.tags||[]).join(','))}"><label>Folder</label><select id="ffolder"><option value="">None</option>${records('folder').map(x=>`<option value="${x.id}" ${f.folder_id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select>`,async()=>patch(f,{title:$('#ftitle').value,project_id:$('#fproject').value,tags:$('#ftags').value.split(',').map(s=>s.trim()).filter(Boolean),folder_id:$('#ffolder').value||null}))}
async function preview(id){const f=record(id);try{const r=await api('/files/'+id+'/content?preview=true');modal(f.title,`<pre>${esc(r.text)}</pre>${r.truncated?'<small>Preview truncated.</small>':''}`,null)}catch(e){modal(f.title,`<p>${esc(e.message)}</p><a href="/api/files/${id}/content" download>Download file</a>`,null)}}
function trashModal(r){modal('Move to recoverable trash?',`<p>${esc(r.title||r.kind)} will leave your workspace. Restore it from Backup & restore. Linked reminders are cancelled when a task is deleted.</p>`,async()=>{await api('/records/'+r.id+'/trash','POST',{confirm:true,version:r.version});await refresh()},'Move to trash')}
async function vaultUnlock(){const s=await api('/vault/status');modal(s.configured?'Unlock vault':'Set up vault',`<p>${s.configured?'Enter your master password. The unlock expires after 5 minutes.':'Choose a unique master password of at least 12 characters. If you forget it, your vault cannot be recovered. Backups do not bypass the master password. No recovery key is created. Store your password safely outside TgTop.'}</p><label>Master password</label><input id="master" type="password" required ${s.configured?'':'minlength="12"'} autocomplete="off">${!s.configured?'<label>Confirm password</label><input id="masterConfirm" type="password" required minlength="12" autocomplete="off"><label><input id="recoveryAgree" type="checkbox" required> I understand that forgotten master passwords cannot be reset to decrypt this vault.</label>':''}`,async()=>{const pass=$('#master').value;if(!s.configured&&pass!==$('#masterConfirm').value)throw Error('Passwords must match');if(!s.configured)await api('/vault/setup','POST',{password:pass});await api('/vault/unlock','POST',{password:pass});await refresh()},s.configured?'Unlock':'Create vault')}
function credentialModal(){modal('Save credential',`<p>Explicit vault unlock required. Your secret is never sent to the assistant.</p><label>Label</label><input id="ctitle" required><label>Project</label><select id="cproject">${projectOptions(project)}</select><label>Username / account</label><input id="cuser"><label>Password or API key</label><input id="csecret" type="password" required autocomplete="off">`,async()=>{await api('/vault/save','POST',{title:$('#ctitle').value,project_id:$('#cproject').value,username:$('#cuser').value,secret:$('#csecret').value});await refresh()})}
function reminderModal(){modal('Schedule reminder',`<label>Task</label><select id="rtask">${records('task').filter(t=>t.status!=='done').map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select><label>Date & time (this device’s timezone)</label><input id="rdate" type="datetime-local" required><label>Channel</label><select id="rchannel">${(state.settings.channels?.length?state.settings.channels:['desktop']).map(c=>`<option>${c}</option>`).join('')}</select><label>Repeat</label><select id="rrepeat"><option value="">Once</option><option>daily</option><option>weekly</option></select>`,async()=>{const task=record($('#rtask').value);if(!task)throw Error('Create a task first');await create('reminder',{task_id:task.id,project_id:task.project_id,due_at:new Date($('#rdate').value).toISOString(),channel:$('#rchannel').value,recurrence:$('#rrepeat').value||null,state:'pending'})})}
async function phoneModal(){const connection=await api('/messaging');if(!connection.configured)throw Error('Connect Photon or Twilio first to send a real verification code.');modal('Configure private phone',`<p>Your number is stored privately in encrypted service settings. Ownership must be verified for live SMS.</p><label>International phone number</label><input id="phone" type="tel" placeholder="${esc(state.phone_masked||'+1 …')}"><p><small>Leave blank to verify the private number already configured.</small></p>`,async()=>{const r=await api('/phone/start','POST',{phone:$('#phone').value});setTimeout(()=>modal('Verify phone',`<p>${esc(r.message)}</p>${r.development_code?`<div class="banner warning">SIMULATOR CODE: ${esc(r.development_code)}<br>No real message was sent.</div>`:''}<label>Code</label><input id="code" required autocomplete="one-time-code">`,async()=>{await api('/phone/verify','POST',{code:$('#code').value});await refresh()},'Verify'),50)},'Send verification')}
function smsModal(){modal('Development SMS command simulator',`<div class="banner warning">No real SMS is sent or received. Complete simulated phone verification first.</div><label>Incoming command</label><input id="simCommand" required placeholder="Remind me tomorrow at 6 PM to submit my assignment"><label>Message ID (reuse to test duplicate rejection)</label><input id="simId" value="${crypto.randomUUID()}"><pre id="simResult">Waiting for command…</pre>`,async()=>{const r=await api('/simulator/sms','POST',{body:$('#simCommand').value,message_id:$('#simId').value});toast(r.answer);await refresh()},'Simulate incoming')}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000)}
function backupModal(workflow){modal('Create encrypted backup',`<p>Choose a backup password of at least 12 characters. Keep it safely; forgotten backup passwords cannot be recovered. This does not replace your vault master password.</p><label>Backup password</label><input id="bpass" type="password" required minlength="12" autocomplete="new-password"><label>Confirm password</label><input id="bconfirm" type="password" required minlength="12" autocomplete="new-password">`,async()=>{if($('#bpass').value!==$('#bconfirm').value)throw Error('Passwords must match');const blob=await api(workflow?'/workflows/'+workflow+'/run':'/backup','POST',{password:$('#bpass').value});download(blob,'TgTop-backup.tgtop');await refresh()},'Create & download')}
function restoreModal(){modal('Restore encrypted backup',`<div class="banner warning">This replaces current service data and revokes all sessions. A pre-restore snapshot is saved using the entered backup password. Protect that file too.</div><label>Backup file</label><input id="restoreFile" type="file" accept=".tgtop" required><label>Backup password</label><input id="restorePass" type="password" required><label>Type RESTORE to confirm</label><input id="restoreConfirm" required pattern="RESTORE">`,async()=>{const f=new FormData();f.append('file',$('#restoreFile').files[0]);f.append('password',$('#restorePass').value);f.append('confirm',$('#restoreConfirm').value);await api('/restore','POST',f);localKey=null;loaded=false;sessionReady=false;loginScreen();toast('Restored. Sign in again.')},'Replace & restore')}
async function notifications(){if(!online)return;for(const d of records('delivery').filter(d=>d.channel==='desktop'&&d.status==='waiting_device')){const body='You have a task reminder. Open TgTop to review it.';if(window.tgtop){const sent=await window.tgtop.notify('TgTop reminder',body);if(sent)await api('/deliveries/'+d.id+'/ack','POST',{})}else if('Notification'in window&&Notification.permission==='granted'){new Notification('TgTop reminder',{body,tag:d.id});await api('/deliveries/'+d.id+'/ack','POST',{})}}}
document.body.classList.toggle('dark',localStorage.getItem('theme')==='dark');
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#globalSearch')?.focus()}if(e.key==='n'&&!e.target.isContentEditable&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&loaded&&!$('#dialog').open)taskModal()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(view==='vault'){api('/vault/lock','POST',{}).catch(()=>{});$('#dialog').close();$('#dialog').innerHTML=''}}});
window.addEventListener('online',()=>{if(sessionReady&&view!=='resume')refresh().catch(e=>toast(e.message))});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
(async()=>{try{const s=await api('/status');accountConfigured=!s.setup;if(s.setup)loginScreen(true);else try{await refresh()}catch{loginScreen()}}catch(err){$('#app').innerHTML=`<div class="login"><div class="brand"><img src="/icon.svg" alt="">TgTop</div><h1>Workspace needs attention</h1><p role="alert">${esc(err.message)}</p><p>Your saved data has not been reset. Account registration is unavailable until the service can read your workspace.</p><button id="retryStartup" class="primary">Try again</button></div>`;$('#retryStartup').onclick=()=>location.reload()}})();
async function refreshChanges(){if(queue.length){await refresh();return}let more=true,changed=false;while(more){const page=await api('/sync?after='+(state.cursor||0));for(const event of page.events){if(!event.record)continue;state.records=state.records.filter(r=>r.id!==event.record.id);state.records.push(event.record);changed=true}more=page.cursor>(state.cursor||0);state.cursor=page.cursor;state.server_time=page.server_time;if(!more||page.events.length<500)break}const metadata=await api('/state?include_records=false');const metadataChanged=JSON.stringify(metadata.settings)!==JSON.stringify(state.settings)||JSON.stringify(metadata.devices)!==JSON.stringify(state.devices)||JSON.stringify(metadata.chatgpt)!==JSON.stringify(state.chatgpt);state={...metadata,records:state.records,cursor:state.cursor};const connectionChanged=!online;online=true;await saveCache();if(changed||metadataChanged||connectionChanged)render();await notifications()}
setInterval(async()=>{if(!loaded||!sessionReady||$('#dialog').open||view==='resume'||view==='assistant')return;try{await refreshChanges()}catch{if(online){online=false;render()}}},15000);

new MutationObserver(()=>{document.querySelectorAll('label').forEach(l=>{const n=l.nextElementSibling;if(n&&['INPUT','SELECT','TEXTAREA'].includes(n.tagName)&&n.id)l.htmlFor=n.id})}).observe(document.body,{childList:true,subtree:true});

async function chatgptModal(){const cfg=await api('/chatgpt');let models=[];if(cfg.connected&&cfg.plan_enabled){try{models=await api('/chatgpt/models')}catch(e){toast(e.message)}}modal('Connect ChatGPT',`<p>Use your eligible ChatGPT plan. TgTop sends your chat and authorized project context to OpenAI. Phone AI sends your request only; stored file contents and model prose never go through Photon. Tokens stay encrypted in the local service. Your existing TgTop account remains linked to its data.</p><p>${cfg.connected?'ChatGPT connected':'ChatGPT not connected'}</p><label>Saved ChatGPT account</label><select id="chatgptAccount"><option value="">Add an account</option>${cfg.accounts.map(a=>`<option value="${esc(a.id)}" ${cfg.active===a.id?'selected':''}>${esc(a.label)} · ${esc(a.id.slice(0,8))}</option>`).join('')}</select><button type="button" id="chatgptContinue">Continue with ChatGPT</button>${models.length?`<label>Model</label><select id="chatgptModel">${models.map(m=>`<option value="${esc(m.slug)}" ${cfg.model===m.slug?'selected':''}>${esc(m.display_name)}</option>`).join('')}</select><button type="button" id="chatgptModelSave">Save model</button>`:''}<p><a href="https://chatgpt.com/settings/usage" target="_blank" rel="noopener noreferrer">Manage plan usage and limits</a></p>${cfg.connected?'<button type="button" id="chatgptDisconnect">Disconnect ChatGPT</button>':''}<p><small>Complete sign-in and permissions in your browser, then return here to choose a model. This connection does not give TgTop access to your ChatGPT conversation history.</small></p>`,null);on('chatgptContinue',async()=>{const r=await api('/chatgpt/start','POST',{account:$('#chatgptAccount').value||null});if(window.tgtop?.chatgptSignIn)await window.tgtop.chatgptSignIn(r.url);else window.open(r.url,'_blank','noopener,noreferrer');toast('Complete sign-in in your browser. This panel will update automatically.');const dialog=$('#dialog');let busy=false;const deadline=Date.now()+600000;const timer=setInterval(async()=>{if(!dialog.open||!$('#chatgptContinue')||Date.now()>deadline){clearInterval(timer);return}if(busy)return;busy=true;try{const next=await api('/chatgpt');if(next.connected&&(next.active!==cfg.active||next.connected!==cfg.connected||next.plan_enabled!==cfg.plan_enabled)){clearInterval(timer);dialog.close();await refresh();await chatgptModal()}}catch{}finally{busy=false}},2500);dialog.addEventListener('close',()=>clearInterval(timer),{once:true})});on('chatgptModelSave',async()=>{await api('/chatgpt/model','POST',{model:$('#chatgptModel').value});$('#dialog').close();await refresh();toast('ChatGPT model saved')});on('chatgptDisconnect',async()=>{const r=await api('/chatgpt/disconnect','POST',{});$('#dialog').close();await refresh();toast(r.message)})}

async function securityModal(){const security=await api('/security');modal('Account security',`<p>Authenticator: ${security.mfa_enabled?'Enabled · '+security.recovery_codes_remaining+' recovery codes remaining':'Not enabled'}</p><button type="button" id="mfaChange">${security.mfa_enabled?'Disable authenticator':'Set up authenticator'}</button><button type="button" id="accountPassword">Change password</button><p>Recovery codes replace a lost authenticator, together with your account password. They do not reset a forgotten account or vault password. Store them outside TgTop.</p>`,null);on('accountPassword',()=>modal('Change account password','<label for="currentPassword">Current password</label><input id="currentPassword" type="password" required autocomplete="current-password"><label for="newPassword">New password</label><input id="newPassword" type="password" required autocomplete="new-password"><label for="repeatPassword">Confirm new password</label><input id="repeatPassword" type="password" required autocomplete="new-password"><p>Changing your password signs out every device.</p>',async()=>{if($('#newPassword').value!==$('#repeatPassword').value)throw Error('Passwords do not match');await api('/account/password','POST',{current_password:$('#currentPassword').value,new_password:$('#newPassword').value});resetAccountView();loginScreen()},'Change password'));on('mfaChange',()=>modal(security.mfa_enabled?'Disable authenticator':'Set up authenticator','<label for="securityPassword">Account password</label><input id="securityPassword" type="password" required autocomplete="current-password">'+(security.mfa_enabled?'<label for="securityCode">New authenticator or recovery code</label><input id="securityCode" required autocomplete="one-time-code">':''),async()=>{if(security.mfa_enabled){await api('/security/totp/disable','POST',{password:$('#securityPassword').value,code:$('#securityCode').value,confirm:true});toast('Authenticator disabled')}else{const result=await api('/security/totp/start','POST',{password:$('#securityPassword').value});setTimeout(()=>authenticatorConfirm(result),0)}},security.mfa_enabled?'Disable':'Continue'))}
function authenticatorConfirm(result){modal('Add TgTop to your authenticator',`<p>In your authenticator app, add a time-based account named TgTop and enter this private setup key. This setup expires in ten minutes.</p><pre>${esc(result.secret)}</pre><label for="authenticatorCode">Six-digit code</label><input id="authenticatorCode" required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"><p>Other devices will be signed out when you enable this.</p>`,async()=>{const confirmed=await api('/security/totp/confirm','POST',{code:$('#authenticatorCode').value});setTimeout(()=>modal('Save your recovery codes',`<p>Each code works once with your account password if you lose your authenticator. Save these codes in a separate safe place. TgTop cannot display them again.</p><pre>${confirmed.recovery_codes.map(esc).join('\n')}</pre>`,null),0)},'Enable authenticator')}
